def norm(s):
 m=min(r for r,c in s); n=min(c for r,c in s); return frozenset((r-m,c-n) for r,c in s)
def variants(s):
 out=[]
 for f in [1,-1]:
  for k in range(4):
   pts=[]
   for r,c in s:
    x,y=r,c*f
    for _ in range(k): x,y=y,-x
    pts.append((x,y))
   out.append(norm(pts))
 return set(out)
