from collections import deque
R,C=len(grid),len(grid[0])
def comps(color):
 seen=set(); out=[]
 for r in range(R):
  for c in range(C):
   if grid[r][c]!=color or (r,c) in seen: continue
   q=[(r,c)]; seen.add((r,c)); pts=[]
   while q:
    x,y=q.pop(); pts.append((x,y))
    for z in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
     if 0<=z[0]<R and 0<=z[1]<C and grid[z[0]][z[1]]==color and z not in seen:
      seen.add(z); q.append(z)
   out.append(pts)
 return out
